package in.sevasetu.amc.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.Cipher;import javax.crypto.spec.GCMParameterSpec;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.Base64;
@Service public class TokenCipher{private final SecretKeySpec key;private final SecureRandom random=new SecureRandom();public TokenCipher(@Value("${app.meta.token-encryption-key}")String encoded){var bytes=Base64.getDecoder().decode(encoded);if(bytes.length!=32)throw new IllegalArgumentException("META_TOKEN_ENCRYPTION_KEY must be a base64-encoded 32-byte key");key=new SecretKeySpec(bytes,"AES");}public String encrypt(String value){try{var iv=new byte[12];random.nextBytes(iv);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));var encrypted=cipher.doFinal(value.getBytes(StandardCharsets.UTF_8));var joined=new byte[iv.length+encrypted.length];System.arraycopy(iv,0,joined,0,iv.length);System.arraycopy(encrypted,0,joined,iv.length,encrypted.length);return Base64.getEncoder().encodeToString(joined);}catch(Exception e){throw new IllegalStateException("Token encryption failed",e);}}public String decrypt(String value){try{var joined=Base64.getDecoder().decode(value);var iv=java.util.Arrays.copyOfRange(joined,0,12);var encrypted=java.util.Arrays.copyOfRange(joined,12,joined.length);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(cipher.doFinal(encrypted),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Token decryption failed",e);}}}
